// DimProcess — generated by src/powerbi/build_assets.py from DimProcess.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimProcess.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"process_key", Int64.Type},
        {"department_id", type text},
        {"operation_type", type text},
        {"process_name", type text}
    }, "en-US")
in
    Typed
